<?php require_once '../config/database.php';require_once '../includes/auth.php';require_once '../includes/ui.php';requireAdmin();$titleForTop='Dashboard Admin';$stats=[];foreach(['PENDING','VERIFIED','CLAIMED','RETURNED','REJECTED'] as $s){$st=$conn->prepare('SELECT COUNT(*) n FROM reports WHERE status=?');$st->bind_param('s',$s);$st->execute();$stats[$s]=$st->get_result()->fetch_assoc()['n'];$st->close();}$st=$conn->query("SELECT COUNT(*) n FROM claims WHERE status IN ('PENDING','FINDER_APPROVED')");$pending=$st->fetch_assoc()['n'];$st=$conn->query('SELECT COUNT(*) n FROM users');$users=$st->fetch_assoc()['n'];$st=$conn->query("SELECT r.id,r.type,r.item_name,r.status,r.created_at,u.name,u.student_status,u.fakultas FROM reports r JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC LIMIT 7");$latest=$st;renderHead('Dashboard Admin');renderAdminNav('dashboard');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Dashboard Admin</h1><p class="muted">Verifikasi laporan, identitas pelapor/penemu, dan penyelesaian klaim.</p></div></div><div class="grid grid-4 stagger"><div class="card stat"><small>Pending Laporan</small><div class="num animate-number"><?= $stats['PENDING'] ?></div></div><div class="card stat"><small>Terverifikasi</small><div class="num animate-number"><?= $stats['VERIFIED'] ?></div></div><div class="card stat"><small>Klaim Perlu Aksi</small><div class="num animate-number"><?= $pending ?></div></div><div class="card stat"><small>Total Pengguna</small><div class="num animate-number"><?= $users ?></div></div></div><div class="section"><div class="grid grid-2"><a class="card" href="reports.php"><h2>📋 Verifikasi Laporan</h2><p class="muted">Periksa laporan LOST dan FOUND beserta data identitas pembuatnya.</p></a><a class="card" href="claims.php"><h2>◇ Verifikasi Klaim</h2><p class="muted">Finalisasi klaim yang sudah disetujui oleh akun penemu.</p></a></div></div><section class="section"><div class="section-head"><h2>Laporan Terbaru</h2><a class="btn btn-light" href="reports.php">Kelola Semua</a></div><div class="table-wrap"><table class="table"><tr><th>Barang</th><th>Jenis</th><th>Pembuat</th><th>Status</th><th>Tanggal</th></tr><?php while($r=$latest->fetch_assoc()): ?><tr><td><b><?= e($r['item_name']) ?></b></td><td><span class="pill <?= $r['type']==='FOUND'?'pill-green':'pill-red' ?>"><?= e($r['type']) ?></span></td><td><?= e($r['name']) ?><br><span class="muted"><?= e($r['student_status']??'-') ?> · <?= e($r['fakultas']??'-') ?></span></td><td><span class="pill pill-yellow"><?= e(statusLabel($r['status'])) ?></span></td><td><?= e($r['created_at']) ?></td></tr><?php endwhile; ?></table></div></section></div><?php renderFooter(); ?>
